// =============================================================================
// Node 2.4 · Parse IfcOpenShell JSON Output
//
// Purpose:
// Converts the JSON produced by the IfcOpenShell extraction script into
// individual n8n items (metadata, elements, and spatial entities).
//
// Expected input (stdout):
// {
//   metadata: {},
//   elements: [],
//   properties: [],
//   quantities: [],
//   materials: [],
//   spatial: []
// }
//
// =============================================================================

// -----------------------------------------------------------------------------
// 1. Read JSON output from Execute Command node
// -----------------------------------------------------------------------------
// IMPORTANT:
// The Python script should print ONLY valid JSON to stdout.
// Any log messages or print statements will cause JSON.parse() to fail.
const rawOutput = $input.first().json.stdout;

// -----------------------------------------------------------------------------
// 2. Parse JSON
// -----------------------------------------------------------------------------
// If parsing fails, inspect:
//   • stdout
//   • stderr
//   • the Python script output
//
// Most common causes:
//   - Python printed debug messages
//   - Empty stdout
//   - Invalid JSON formatting
let parsed;

try {
  parsed = JSON.parse(rawOutput);
} catch (e) {
  return [{
    json: {
      error: 'Failed to parse IfcOpenShell output',
      raw: rawOutput ? rawOutput.substring(0, 500) : 'empty',
      stderr: $input.first().json.stderr || ''
    }
  }];
}

// -----------------------------------------------------------------------------
// 3. Stop early if the extraction script returned an error
// -----------------------------------------------------------------------------
// Expected format:
// {
//     "error": "..."
// }
//
// Debug Python-side issues before investigating this JavaScript.
if (parsed.error) {
  return [{ json: { error: parsed.error, pipeline: 'B' } }];
}

// -----------------------------------------------------------------------------
// 4. Build lookup tables
// -----------------------------------------------------------------------------
// Instead of filtering every property/quantity for every element (O(n²)),
// index everything once by GlobalId (approximately O(n)).
//
// If properties, quantities or materials appear missing,
// first verify that their GlobalId matches the corresponding element.
const propsByGid = {};
for (const p of (parsed.properties || [])) {
  if (!propsByGid[p.GlobalId]) propsByGid[p.GlobalId] = [];
  propsByGid[p.GlobalId].push(p);
}

const qtsByGid = {};
for (const q of (parsed.quantities || [])) {
  if (!qtsByGid[q.GlobalId]) qtsByGid[q.GlobalId] = [];
  qtsByGid[q.GlobalId].push(q);
}

const matByGid = {};
for (const m of (parsed.materials || [])) {
  matByGid[m.GlobalId] = m;
}

const items = [];

// -----------------------------------------------------------------------------
// 5. Create metadata item
// -----------------------------------------------------------------------------
// Metadata is returned as its own n8n item so downstream nodes can process
// project-level information independently from IFC elements.
items.push({
  json: {
    _type: 'metadata',
    pipeline: 'ifcopenshell',
    ...parsed.metadata
  }
});

// -----------------------------------------------------------------------------
// 6. Process IFC elements
// -----------------------------------------------------------------------------
// Each IFC element becomes one n8n item.
//
// The node merges:
//   • Basic element information
//   • Properties
//   • Quantities
//   • Material
//
// Result:
// One flat JSON object per IFC element.
for (const elem of parsed.elements) {

  const gid = elem.GlobalId;

  // ---------------------------------------------------------------------------
  // Merge all properties belonging to this element.
  //
  // Output key format:
  //   [PropertySet] PropertyName
  //
  // Example:
  //   [Pset_WallCommon] FireRating
  //
  // NOTE:
  // Duplicate property names inside the same PropertySet will overwrite
  // previous values because JavaScript object keys must be unique.
  // ---------------------------------------------------------------------------
  const elemProps = (propsByGid[gid] || []).reduce((acc, p) => {
    acc[`[${p.PropertySet}] ${p.Property}`] = p.Value;
    return acc;
  }, {});

  // ---------------------------------------------------------------------------
  // Merge quantities.
  //
  // Numeric strings are converted into JavaScript numbers.
  //
  // IMPORTANT:
  // Using isNaN() preserves legitimate values such as 0.
  // Avoid checking "if(num)" because zero is a valid quantity.
  // ---------------------------------------------------------------------------
  const elemQtys = (qtsByGid[gid] || []).reduce((acc, q) => {
    const num = parseFloat(q.Value);
    acc[`[${q.QuantitySet}] ${q.Quantity}`] = isNaN(num) ? q.Value : num;
    return acc;
  }, {});

  // ---------------------------------------------------------------------------
  // Retrieve material for this element.
  //
  // If Material is unexpectedly empty:
  //   • Check IFC material assignments.
  //   • Verify the extractor exported "materials".
  //   • Confirm matching GlobalIds.
  // ---------------------------------------------------------------------------
  const elemMat = matByGid[gid];

  items.push({
    json: {
      _type: 'element',
      pipeline: 'B_ifcopenshell',

      GlobalId: gid,
      Name: elem.Name,
      Category: elem.Category,
      ObjectType: elem.ObjectType,
      Description: elem.Description,

      is_external: elem.is_external ?? false,

      Material: elemMat ? elemMat.Material : '',

      // Flattened property values
      ...elemProps,

      // Flattened quantity values
      ...elemQtys
    }
  });
}

// -----------------------------------------------------------------------------
// 7. Output spatial hierarchy
// -----------------------------------------------------------------------------
// Spatial entities are exported separately because downstream nodes use them
// for hierarchy reconstruction and domain detection.
//
// Typical IFC spatial objects:
//   • IfcProject
//   • IfcSite
//   • IfcBuilding
//   • IfcBuildingStorey
//   • IfcSpace
//
// If hierarchy appears incomplete, inspect parsed.spatial before this loop.
for (const s of (parsed.spatial || [])) {
  items.push({
    json: {
      _type: 'spatial_entity',
      pipeline: 'B_ifcopenshell',

      GlobalId: s.GlobalId,
      Name: s.Name,
      Category: s.Type,

      ParentGlobalId: s.ParentGlobalId,
      ParentName: s.ParentName,
    }
  });
}

// -----------------------------------------------------------------------------
// 8. Return all generated items
// -----------------------------------------------------------------------------
// Output consists of multiple n8n items:
//
//   metadata
//   element
//   element
//   ...
//   spatial_entity
//   spatial_entity
//
// Downstream nodes can filter using the "_type" field.
return items;

// =============================================================================
// Node 2.5 · IFC Schema & Domain Detection
//
// Purpose:
// Determines the IFC schema and infrastructure domain (Building, Bridge,
// Road, Rail, Mixed, or Unknown) from the extracted IFC data.
//
// Output:
// Adds two fields to every n8n item:
//
//   ifc_schema
//   ifc_domain
//
// Assumptions:
// • All input items originate from the previous extraction node.
// • Exactly one metadata item exists.
// • Metadata contains the IFC schema.
// =============================================================================

const all = $input.all();

// -----------------------------------------------------------------------------
// 1. Retrieve metadata
// -----------------------------------------------------------------------------
// The metadata item contains project-wide information such as IFC schema.
//
// If no metadata exists, default to IFC4 since most building models use it.
const meta = all.find(i => i.json._type === 'metadata');

const schema = (meta?.json?.schema || 'IFC4').toUpperCase();

// -----------------------------------------------------------------------------
// 2. Collect all unique element and spatial categories
// -----------------------------------------------------------------------------
// Using Sets allows efficient existence checks when determining the domain.
//
// Example element categories:
//   IfcWall
//   IfcSlab
//   IfcTrackElement
//
// Example spatial categories:
//   IfcBuilding
//   IfcBridge
//   IfcRoad
const categories = new Set(
  all
    .filter(i => i.json._type === 'element' && i.json.Category)
    .map(i => i.json.Category)
);

const spatialTypes = new Set(
  all
    .filter(i => i.json._type === 'spatial_entity' && i.json.Category)
    .map(i => i.json.Category)
);

// -----------------------------------------------------------------------------
// 3. Determine IFC domain
// -----------------------------------------------------------------------------
//
// IFC4
// -----
// IFC4 generally represents building models, so "Building" is used as the
// default domain.
//
// IFC4X3
// -------
// IFC4X3 introduces dedicated infrastructure entities (Road, Rail, Bridge).
// The domain is inferred by checking for characteristic element and spatial
// entity types.
//
// NOTE:
// If additional IFC4X3 infrastructure entities are introduced in future
// versions, extend the checks below.
//
let domain = 'Building';

if (schema.startsWith('IFC4X3')) {

  // Rail indicators
  const hasRail =
    categories.has('IfcRail') ||
    categories.has('IfcTrackElement') ||
    spatialTypes.has('IfcRailway');

  // Road indicators
  const hasRoad =
    categories.has('IfcPavement') ||
    categories.has('IfcKerb') ||
    spatialTypes.has('IfcRoad');

  // Bridge indicators
  const hasBridge =
    categories.has('IfcBearing') ||
    categories.has('IfcDeepFoundation') ||
    spatialTypes.has('IfcBridge');

  // Building indicators
  const hasBuilding =
    spatialTypes.has('IfcBuilding') ||
    categories.has('IfcWall') ||
    categories.has('IfcSlab');

  // ---------------------------------------------------------------------------
  // Count how many domains are detected.
  //
  // Mixed models (e.g. Road + Bridge) are labelled as "Mixed" instead of
  // assigning a single domain.
  // ---------------------------------------------------------------------------
  const matches = [
    hasRail,
    hasRoad,
    hasBridge,
    hasBuilding
  ].filter(Boolean).length;

  if      (matches > 1) domain = 'Mixed';
  else if (hasRail)     domain = 'Rail';
  else if (hasRoad)     domain = 'Road';
  else if (hasBridge)   domain = 'Bridge';
  else if (hasBuilding) domain = 'Building';
  else                  domain = 'Unknown';
}

// -----------------------------------------------------------------------------
// 4. Append schema and domain to every output item
// -----------------------------------------------------------------------------
// These fields allow downstream nodes to identify both the IFC schema and
// inferred project domain without reprocessing the dataset.
return all.map(item => ({
  json: {
    ...item.json,
    ifc_schema: schema,
    ifc_domain: domain
  }
}));

const items = $input.all();

const EXPOSURE_BUILDING = {
  IfcRoof:                { base: 0.90, ext: 0.90 },
  IfcChimney:             0.80,
  IfcStair:               0.60,
  IfcStairFlight:         0.60,
  IfcRamp:                0.55,
  IfcRampFlight:          0.55,
  IfcWall:                { base: 0.45, ext: 0.40 },
  IfcWallStandardCase:    { base: 0.45, ext: 0.40 },
  IfcWindow:              { base: 0.50, ext: 0.45 },
  IfcDoor:                { base: 0.40, ext: 0.35 },
  IfcColumn:              0.55,
  IfcColumnStandardCase:  0.55,
  IfcBeam:                0.50,
  IfcBeamStandardCase:    0.50,
  IfcSlab:                0.55,
  IfcSlabStandardCase:    0.55,
  IfcFooting:             0.65,
  IfcPile:                0.60,
  IfcPlate:               0.45,
  IfcMember:              0.40,
  IfcCovering:            0.35,
  IfcCurtainWall:         { base: 0.60, ext: 0.55 },
  IfcFurnishingElement:   0.10,
  IfcFurniture:           0.10,
  IfcRailing:             0.35,
  IfcSpace:               0.20,
  IfcBuildingElementProxy: 0.30,
};

const EXPOSURE_ROAD = {
  IfcPavement:            0.85,
  IfcKerb:                0.70,
  IfcRoadPart:            0.75,
  IfcEarthworksFill:      0.60,
  IfcEarthworksCut:       0.60,
  IfcCourse:              0.80,
  IfcSignal:              0.50,
  IfcSign:                0.45,
  IfcCivilElement:        0.55,
};

const EXPOSURE_RAIL = {
  IfcRail:                0.80,
  IfcTrackElement:        0.75,
  IfcFacilityPart:        0.60,
  IfcCivilElement:        0.55,
  IfcEarthworksFill:      0.55,
  IfcEarthworksCut:       0.55,
  IfcSignal:              0.70,
  IfcSign:                0.40,
};

const EXPOSURE_BRIDGE = {
  IfcBridgePart:          0.85,
  IfcBearing:             0.80,
  IfcCourse:              0.75,
  IfcCivilElement:        0.70,
  IfcColumn:              0.65,
  IfcColumnStandardCase:  0.65,
  IfcBeam:                0.70,
  IfcBeamStandardCase:    0.70,
  IfcSlab:                0.65,
  IfcSlabStandardCase:    0.65,
  IfcEarthworksFill:      0.50,
  IfcEarthworksCut:       0.50,
  IfcDeepFoundation:      0.60,
};

const DEFAULT_EXPOSURE = 0.30;

function inferDomain(ifcType, explicitDomain) {
  if (explicitDomain && explicitDomain !== 'Unknown') return explicitDomain;
  if (['IfcRail', 'IfcTrackElement'].includes(ifcType))           return 'Rail';
  if (['IfcBridgePart', 'IfcBearing'].includes(ifcType))          return 'Bridge';
  if (['IfcPavement', 'IfcKerb', 'IfcRoadPart'].includes(ifcType)) return 'Road';
  return 'Building';
}

function selectTable(domain) {
  if (domain === 'Road')   return { table: EXPOSURE_ROAD,     warn: false };
  if (domain === 'Rail')   return { table: EXPOSURE_RAIL,     warn: false };
  if (domain === 'Bridge') return { table: EXPOSURE_BRIDGE,   warn: false };
  if (domain === 'Mixed')  return { table: EXPOSURE_BUILDING, warn: true  };
  return                          { table: EXPOSURE_BUILDING, warn: false };
}

function resolveEntry(entry, isExternal) {
  if (entry === undefined || entry === null) return null;
  if (typeof entry === 'number') return entry;
  if (typeof entry === 'object') return isExternal ? entry.ext : entry.base;
  return null;
}

function readIsExternal(json) {
  if (typeof json.is_external === 'boolean') return json.is_external;
  return Object.keys(json).some(k =>
    k.includes('IsExternal') &&
    (json[k] === true || json[k] === 'true' || json[k] === '.T.')
  );
}

return items.map(item => {
  if (item.json._type !== 'bqi_scored') return item;

  const json       = item.json;
  const ifcType    = json.Category || '';
  const isExternal = readIsExternal(json);
  const domain     = inferDomain(ifcType, json.ifc_domain || 'Unknown');

  if (!ifcType) {
    return {
      json: {
        ...json,
        _type:          'risk_exposure',
        exposure_score: DEFAULT_EXPOSURE,
        is_external:    isExternal,
        domain:         domain,
        domain_warning: true,
      }
    };
  }

  const { table, warn } = selectTable(domain);
  const entry           = table[ifcType];
  const resolved        = resolveEntry(entry, isExternal);
  const exposureScore   = resolved !== null ? resolved : DEFAULT_EXPOSURE;

  return {
    json: {
      ...json,
      _type:          'risk_exposure',
      exposure_score: exposureScore,
      is_external:    isExternal,
      domain:         domain,
      ...(warn && { domain_warning: true }),
    }
  };
});

// =============================================================================
// Node 3.2 · Quantity Take-Off (QTO) Comparison
//
// Purpose:
// Compares Quantity Take-Off (QTO) values extracted from two pipelines:
//
//   • Pipeline A (DDC Toolkit)
//   • Pipeline B (IfcOpenShell)
//
// Elements are matched using their IFC GlobalId. Matching QTO fields are then
// compared to identify differences in extracted quantities.
//
// Outputs:
//   • qto_summary      : Overall comparison statistics
//   • element          : Original element records (passed through)
//   • qto_comparison   : One record per compared QTO field
//
// Assumptions:
// • Both pipelines use the same IFC GlobalId for the same physical element.
// • Quantity fields follow the naming convention:
//       [QuantitySet] QuantityName
// =============================================================================


// -----------------------------------------------------------------------------
// Build element lookups
// -----------------------------------------------------------------------------
// Create dictionaries indexed by GlobalId for fast element matching.
//
// Performance:
// Lookup by GlobalId is O(1), avoiding repeated searches through the full
// dataset.
//
const qtoPattern = /^\[.*?\]/;

const lookupA = {};
const lookupB = {};

for (const item of $input.all()) {
  const el = item.json;

  if (el._type !== 'element') continue;

  if (el.pipeline === 'A_ddc') {
    lookupA[el.GlobalId] = el;
  } else if (el.pipeline === 'B_ifcopenshell') {
    lookupB[el.GlobalId] = el;
  }
}

// Elements available in both extraction pipelines.
const sharedGids = Object.keys(lookupA).filter(gid => lookupB[gid]);


// =============================================================================
// Helper Functions
// =============================================================================

// -----------------------------------------------------------------------------
// Normalize quantity field names.
//
// Different extraction tools may use different Quantity Set names:
//
//   [BaseQuantities] NetVolume
//   [Qto_WallBaseQuantities] NetVolume
//
// Both become:
//
//   NetVolume
//
// This allows quantities with the same meaning to be compared regardless of
// their originating Quantity Set.
// -----------------------------------------------------------------------------
function normalizeQtoKey(key) {
  return key.replace(/^\[.*?\][.\s]/, '').trim();
}


// -----------------------------------------------------------------------------
// Extract QTO fields from an element.
//
// Returns:
//
// {
//     NetVolume : {
//         value: 15.4,
//         originalKey: "[BaseQuantities] NetVolume"
//     }
// }
//
// Notes:
// • Only fields beginning with "[...]" are treated as quantities.
// • If duplicate normalized names exist, the first occurrence is kept.
// -----------------------------------------------------------------------------
function getQtoMap(obj) {

  const map = {};

  for (const key of Object.keys(obj)) {

    if (qtoPattern.test(key)) {

      const normalized = normalizeQtoKey(key);

      if (!map[normalized]) {
        map[normalized] = {
          value: parseFloat(obj[key]),
          originalKey: key
        };
      }
    }
  }

  return map;
}


// =============================================================================
// Compare quantities
// =============================================================================

const comparisons = [];
const deltas = [];

for (const gid of sharedGids) {

  const a = lookupA[gid];
  const b = lookupB[gid];

  const qtoA = getQtoMap(a);
  const qtoB = getQtoMap(b);

  // Union of all quantity names from both extraction methods.
  const allQtoKeys = new Set([
    ...Object.keys(qtoA),
    ...Object.keys(qtoB)
  ]);

  for (const qtoKey of allQtoKeys) {

    const entryA = qtoA[qtoKey];
    const entryB = qtoB[qtoKey];

    const valA = entryA?.value;
    const valB = entryB?.value;

    const hasA = entryA !== undefined && !isNaN(valA);
    const hasB = entryB !== undefined && !isNaN(valB);

    let delta   = null;
    let pctDiff = null;
    let match   = 'missing';

    if (hasA && hasB) {

      // Absolute difference between extraction methods.
      delta = valB - valA;

      // Percentage difference relative to Pipeline A.
      pctDiff =
        valA !== 0
          ? Math.abs(delta) / Math.abs(valA) * 100
          : 0;

      // -----------------------------------------------------------------------
      // Match classification
      //
      // exact        : numerically identical
      // negligible   : <0.01%
      // minor        : <1%
      // significant  : ≥1%
      //
      // Thresholds may be adjusted depending on the required comparison
      // sensitivity.
      // -----------------------------------------------------------------------
      if      (Math.abs(delta) < 1e-10) match = 'exact';
      else if (pctDiff < 0.01)          match = 'negligible';
      else if (pctDiff < 1)             match = 'minor';
      else                              match = 'significant';

      deltas.push({
        gid,
        field: qtoKey,
        delta,
        pctDiff
      });

    } else {

      // Quantity exists in only one extraction pipeline.
      match = hasA ? 'only_in_A' : 'only_in_B';
    }

    comparisons.push({
      _type:      'qto_comparison',

      GlobalId:   gid,
      Name:       a.Name || b.Name || '',
      Category:   a.Category || b.Category || '',

      QtoField:   qtoKey,

      QtoField_A: entryA?.originalKey || null,
      QtoField_B: entryB?.originalKey || null,

      Value_A:    hasA ? valA : null,
      Value_B:    hasB ? valB : null,

      Delta:      delta,
      PctDiff:    pctDiff,

      Match:      match
    });
  }
}


// =============================================================================
// Build summary statistics
// =============================================================================
//
// Reports:
//
// • Total elements in each extraction pipeline
// • Shared elements
// • Elements unique to each pipeline
// • Counts grouped by IFC category
//
// Useful for identifying extraction coverage differences.
//
const onlyInAGids = Object.keys(lookupA).filter(gid => !lookupB[gid]);
const onlyInBGids = Object.keys(lookupB).filter(gid => !lookupA[gid]);

function countByType(gids, lookup) {

  const counts = {};

  for (const gid of gids) {

    const type = lookup[gid].Category || 'Unknown';

    counts[type] = (counts[type] || 0) + 1;
  }

  return counts;
}

const summary = {

  _type: 'qto_summary',

  total_elements_A: Object.keys(lookupA).length,
  total_elements_B: Object.keys(lookupB).length,

  shared_elements: sharedGids.length,

  total_unique_elements:
    sharedGids.length +
    onlyInAGids.length +
    onlyInBGids.length,

  only_in_A: onlyInAGids.length,
  only_in_B: onlyInBGids.length,

  only_in_A_by_type: countByType(onlyInAGids, lookupA),
  only_in_B_by_type: countByType(onlyInBGids, lookupB)
};


// -----------------------------------------------------------------------------
// Pass through original elements.
//
// This allows downstream nodes to continue using the original extracted
// elements alongside the comparison results.
// -----------------------------------------------------------------------------
const passthrough =
  $input.all().filter(item => item.json._type === 'element');


// =============================================================================
// Output
//
// 1. Summary statistics
// 2. Original element records
// 3. One comparison record per QTO field
// =============================================================================
return [
  { json: summary },
  ...passthrough,
  ...comparisons.map(c => ({ json: c }))
];

const items = $input.all();

const summaryItem = items.find(i => i.json._type === 'qto_summary');

if (!summaryItem) {
  return [{
    json: {
      _type: 'error',
      message: 'No qto_summary found. Check that Node 3.2 ran correctly.'
    }
  }];
}

const summary = summaryItem.json;

// Read coverage threshold from Config, fallback to 95
const coverageThreshold = $node['0.1: Config']?.json?.coverage_threshold ?? 95;

// ----------------------------------------------------------------------
// IFC type severity rules.
// These classify how serious it is when an element type appears in one
// extraction pipeline but not the other:
//   critical          -> load-bearing or space-defining elements. A missing
//                        one means quantities/risk screening may be wrong.
//   needs_review      -> secondary or ambiguous elements (incl. proxies and
//                        any type not listed anywhere = conservative default).
//   probably_harmless -> non-physical schema constructs; their absence does
//                        not change quantities or structural risk.
// The critical list mirrors the high-criticality types in Node 4.3
// (CRITICALITY_BUILDING >= 0.75), keeping severity and consequence aligned.
// ----------------------------------------------------------------------

const criticalTypes = [
  'IfcWall', 'IfcWallStandardCase',
  'IfcSlab', 'IfcSlabStandardCase',
  'IfcBeam', 'IfcBeamStandardCase',
  'IfcColumn', 'IfcColumnStandardCase',
  'IfcRoof', 'IfcDoor', 'IfcWindow',
  'IfcSpace', 'IfcStair', 'IfcStairFlight',
  'IfcRamp', 'IfcRampFlight',
  'IfcFooting', 'IfcPile'
];

const reviewTypes = [
  'IfcCovering', 'IfcPlate', 'IfcMember', 'IfcRailing',
  'IfcCurtainWall', 'IfcFurnishingElement', 'IfcFurniture',
  'IfcBuildingElementProxy'
];

// Non-physical or annotation-level entities. A count mismatch in these
// types does not affect quantities or structural risk screening.
const harmlessTypes = [
  'IfcOpeningElement', 'IfcOpeningStandardCase',
  'IfcAnnotation', 'IfcGrid', 'IfcGridAxis',
  'IfcVirtualElement'
];

function classify(type) {
  if (criticalTypes.includes(type)) return 'critical';
  if (harmlessTypes.includes(type)) return 'probably_harmless';
  if (reviewTypes.includes(type))   return 'needs_review';
  return 'needs_review'; // unknown types are treated conservatively
}

// --------------------
// Count severity, without double-penalizing
// --------------------

const severity = { critical: 0, needs_review: 0, probably_harmless: 0 };
const typesBySeverity = { critical: [], needs_review: [], probably_harmless: [] };

const missingAByType = summary.only_in_A_by_type || {};
const missingBByType = summary.only_in_B_by_type || {};

// An element missing from A and also missing from B would otherwise be
// counted twice; taking the max over the union of types counts it once.
const allMissingTypes = new Set([
  ...Object.keys(missingAByType),
  ...Object.keys(missingBByType)
]);

for (const type of allMissingTypes) {
  const maxCount = Math.max(
    missingAByType[type] || 0,
    missingBByType[type] || 0
  );
  const bucket = classify(type);
  severity[bucket] += maxCount;
  if (maxCount > 0) typesBySeverity[bucket].push(`${type} (${maxCount})`);
}

// --------------------
// Coverage % = elements found by BOTH pipelines / all unique elements
// (union denominator, so the percentage is symmetric in A and B).
// --------------------

const totalUnique = summary.total_unique_elements
  || Math.max(summary.total_elements_A, summary.total_elements_B);

const coveragePct = totalUnique > 0
  ? Math.round((summary.shared_elements / totalUnique) * 10000) / 100
  : 0;

// --------------------
// Verdict logic:
//   any critical missing            -> FAIL  (HIGH risk)
//   review items or low coverage    -> REVIEW (MEDIUM risk)
//   otherwise                       -> PASS  (LOW risk)
// probably_harmless never affects the verdict, by design.
// --------------------

let verdict   = 'PASS';
let riskLevel = 'LOW';

if (severity.critical > 0) {
  verdict   = 'FAIL';
