const allItems = $input.all();

const qtoComparisons = allItems.filter(i => i.json._type === 'qto_comparison');
const elements       = allItems.filter(i => i.json._type === 'element');

if (!elements.length) {
  return [{
    json: {
      _type: 'error',
      message: 'No element items found — check Node 3.1 merge and Node 2.6 filter'
    }
  }];
}

const qtoByGid = {};
for (const comp of qtoComparisons) {
  const gid = comp.json.GlobalId;
  if (!qtoByGid[gid]) qtoByGid[gid] = [];
  qtoByGid[gid].push(comp.json);
}

// BQI dimension weights. Normally read from Node 0.1 Config (bqi_weights).
// The object below is only a safety fallback if Config is missing.
// Weight rationale: completeness > validity > the two QTO dimensions (equal).
const WEIGHTS = $node['0.1: Config']?.json?.bqi_weights || {
  completeness:  0.35,
  validity:      0.25,
  qto_coverage:  0.20,
  qto_agreement: 0.20
};

const REQUIRED_PROPS = {
  IfcWall:                  ['IsExternal', 'LoadBearing'],
  IfcWallStandardCase:      ['IsExternal', 'LoadBearing'],
  IfcSlab:                  ['IsExternal', 'LoadBearing'],
  IfcSlabStandardCase:      ['IsExternal', 'LoadBearing'],
  IfcBeam:                  ['IsExternal', 'LoadBearing'],
  IfcBeamStandardCase:      ['IsExternal', 'LoadBearing'],
  IfcColumn:                ['IsExternal', 'LoadBearing'],
  IfcColumnStandardCase:    ['IsExternal', 'LoadBearing'],
  IfcRoof:                  ['IsExternal'],
  IfcDoor:                  ['IsExternal', 'FireRating'],
  IfcWindow:                ['IsExternal'],
  IfcSpace:                 ['IsExternal', 'GrossPlannedArea'],
};

const EXPECTED_QTO = {
  IfcWall:                  ['NetVolume', 'Width', 'Length', 'NetSideArea'],
  IfcWallStandardCase:      ['NetVolume', 'Width', 'Length', 'NetSideArea'],
  IfcSlab:                  ['NetVolume', 'Depth', 'NetArea'],
  IfcSlabStandardCase:      ['NetVolume', 'Depth', 'NetArea'],
  IfcBeam:                  ['NetVolume', 'Length'],
  IfcBeamStandardCase:      ['NetVolume', 'Length'],
  IfcColumn:                ['NetVolume', 'Length'],
  IfcColumnStandardCase:    ['NetVolume', 'Length'],
  IfcRoof:                  ['NetVolume'],
  IfcSpace:                 ['NetFloorArea', 'GrossFloorArea', 'Height'],
  IfcDoor:                  ['Area', 'Height', 'Width'],
  IfcWindow:                ['Area', 'Height', 'Width'],
};

// Checks whether an element carries a property with EXACTLY this name.
// Keys look like "[Pset_WallCommon] IsExternal"; we compare the part after
// the bracket. Exact match prevents e.g. 'Area' wrongly matching 'NetArea'.
function hasProperty(elem, propName) {
  return Object.keys(elem).some(k => {
    const match = k.match(/^\[.*?\]\s(.+)$/);
    return match && match[1] === propName
        && elem[k] != null && elem[k] !== '';
  });
}

function scoreElement(elem) {
  const type = elem.Category || '';
  const gid  = elem.GlobalId;

  // hasAnyData = does this element carry ANY property/quantity at all?
  // Used as a conservative fallback for IFC types that have no rule in the
  // REQUIRED_PROPS / EXPECTED_QTO tables above: with data -> score 1.0,
  // with no data at all -> score 0.0 (never "perfect by default").
  const propKeys  = Object.keys(elem).filter(k => k.startsWith('['));
  const hasAnyData = propKeys.length > 0;

  // D1 Completeness = (required properties found) / (required properties)
  // for this IFC type, per the REQUIRED_PROPS table.
  const required     = REQUIRED_PROPS[type] || [];
  const missingProps = required.filter(p => !hasProperty(elem, p));
  const completenessScore = required.length > 0
    ? (required.length - missingProps.length) / required.length
    // No rule for this type: fall back to the hasAnyData rule (see above).
    : (hasAnyData ? 1.0 : 0.0);

  // D2 Validity = (property values that are usable) / (all extracted
  // properties). A value is invalid if it is empty, null, UNSET, or N/A.
  const invalidProps = propKeys.filter(k => {
    const v = elem[k];
    return v === '' || v === null || v === undefined
        || v === "['UNSET']" || v === 'UNSET' || v === 'N/A';
  });
  const validityScore = propKeys.length > 0
    ? (propKeys.length - invalidProps.length) / propKeys.length
    // No properties extracted at all -> validity is 0, not "valid by default".
    : 0.0;

  // D3 QTO coverage = (expected quantities found) / (expected quantities)
  // for this IFC type, per the EXPECTED_QTO table.
  const expectedQto      = EXPECTED_QTO[type] || [];
  const missingQto       = expectedQto.filter(qty => !hasProperty(elem, qty));
  const qtoCoverageScore = expectedQto.length > 0
    ? (expectedQto.length - missingQto.length) / expectedQto.length
    // No rule for this type: same hasAnyData fallback as D1.
    : (hasAnyData ? 1.0 : 0.0);

  // D4 QTO agreement = share of Pipeline A vs B quantity comparisons for
  // this element that matched (exact or negligible difference).
  // If quantities were expected but no comparison exists, we assign 0.5:
  // absence of evidence is penalized, but not treated as total disagreement.
  const qtoComps = qtoByGid[gid] || [];
  const qtoAgreementScore = qtoComps.length > 0
    ? qtoComps.filter(c => c.Match === 'exact' || c.Match === 'negligible').length / qtoComps.length
    // No comparison rows for this element: see the 0.5 rule explained above.
    : (expectedQto.length === 0 ? (hasAnyData ? 1.0 : 0.0) : 0.5);

  const bqi =
    WEIGHTS.completeness  * completenessScore  +
    WEIGHTS.validity      * validityScore      +
    WEIGHTS.qto_coverage  * qtoCoverageScore   +
    WEIGHTS.qto_agreement * qtoAgreementScore;

  const confidence =
    bqi >= 0.85 ? 'high'   :
    bqi >= 0.60 ? 'medium' : 'low';

  const penalties = [];
  if (completenessScore  < 0.5) penalties.push('incomplete_properties');
  if (validityScore      < 0.5) penalties.push('invalid_values');
  if (qtoCoverageScore   < 0.5) penalties.push('missing_qto');
  if (qtoAgreementScore  < 0.5) penalties.push('qto_disagreement');
  if (!elem.Material || elem.Material === '') penalties.push('no_material');

  return {
    _type:               'bqi_scored',
    GlobalId:            gid,
    Name:                elem.Name       || '',
    Category:            type,
    Material:            elem.Material   || '',
    ObjectType:          elem.ObjectType || '',
    is_external:         elem.is_external ?? false,
    pipeline:            elem.pipeline   || '',
    ifc_domain:          elem.ifc_domain || 'Building',
    ifc_schema:          elem.ifc_schema || '',
    bqi_score:           bqi,
    bqi_confidence:      confidence,
    score_completeness:  completenessScore,
    score_validity:      validityScore,
    score_qto_coverage:  qtoCoverageScore,
    score_qto_agreement: qtoAgreementScore,
    missing_properties:  missingProps,
    invalid_properties:  invalidProps,
    missing_qto:         missingQto,
    penalties,
    // All bracketed keys — covers [Pset_], [Qto_], [BaseQuantities]
    ...Object.fromEntries(Object.entries(elem).filter(([k]) => k.startsWith('[')))
  };
}

// Element-level scoring uses Pipeline B (IfcOpenShell) when available,
// because it is the richer extraction; Pipeline A is the fallback.
// This choice also fixes which BQI feeds the risk formula in Block 4.
const elementsToScore = (() => {
  const b = elements.filter(i => i.json.pipeline === 'B_ifcopenshell');
  return b.length > 0 ? b : elements.filter(i => i.json.pipeline === 'A_ddc');
})();

const scored = elementsToScore.map(elem => ({ json: scoreElement(elem.json) }));

const avgBqi = scored.length > 0
  ? scored.reduce((s, i) => s + i.json.bqi_score, 0) / scored.length
  : 0;

// ---- Per-pipeline dimension averages (feeds the A-vs-B radar in 5.6) ------
// Element-level scoring (and the risk formula) still uses Pipeline B only;
// this block is additive and only feeds the model summary / radar chart.
// Note: D4 is inherently cross-pipeline agreement, so it is the same value
// for both pipelines — the radar shows D1–D3 per pipeline, D4 as shared axis.
function dimAverages(elems) {
  if (!elems.length) return null;
  const s = elems.map(e => scoreElement(e.json));
  const avg = k => s.reduce((a, x) => a + (x[k] || 0), 0) / s.length;
  return {
    n: s.length,
    D1_completeness:  avg('score_completeness'),
    D2_validity:      avg('score_validity'),
    D3_qto_coverage:  avg('score_qto_coverage'),
    D4_qto_agreement: avg('score_qto_agreement'),
    bqi:              avg('bqi_score'),
  };
}
const dimsByPipeline = {
  A_ddc:          dimAverages(elements.filter(i => i.json.pipeline === 'A_ddc')),
  B_ifcopenshell: dimAverages(elements.filter(i => i.json.pipeline === 'B_ifcopenshell')),
};

const output = [];

output.push({
