    model_bqi: avgBqi,
    model_confidence:      avgBqi >= 0.85 ? 'high' : avgBqi >= 0.60 ? 'medium' : 'low',
    total_elements_scored: scored.length,
    pipeline_scored:       elementsToScore[0]?.json?.pipeline || 'unknown',
    distribution: {
      high:   scored.filter(i => i.json.bqi_confidence === 'high').length,
      medium: scored.filter(i => i.json.bqi_confidence === 'medium').length,
      low:    scored.filter(i => i.json.bqi_confidence === 'low').length,
    },
    weights_used:             WEIGHTS,
    // ⚠️ Key name must match what Node 5.6 reads: dim_averages_by_pipeline
    dim_averages_by_pipeline: dimsByPipeline,
  }
});

scored.forEach(row => output.push(row));

allItems.forEach(item => {
  if (item.json._type === 'qto_comparison' || item.json._type === 'coverage_analysis') {
    output.push(item);
  }
});

return output;

const items = $input.all();

const comparisons = items.filter(
  i => i.json._type === 'qto_comparison'
    && i.json.Value_A !== null
    && i.json.Value_B !== null
);

const output = [];

if (!comparisons.length) {
  // ✅ Emit an honest "nothing to correlate" summary instead of an error —
  // and still pass everything else through instead of discarding it.
  output.push({
    json: {
      _type:                'srcc_summary',
      total_fields_scored:  0,
      stable_fields:        0,
      unstable_fields:      0,
      average_srcc:         null,
      overall_rank_stable:  false,
      overall_note:         'No qto_comparison rows had both Value_A and Value_B present — SRCC cannot be computed for this run',
      srcc_results:         []
    }
  });
  items.forEach(item => {
    if (item.json._type !== 'qto_comparison') {
      output.push(item);
    }
  });
  return output;
}

// ✅ Group by Category + QtoField for meaningful per-type SRCC
const qtoGroups = {};
comparisons.forEach(item => {
  const key = `${item.json.Category}::${item.json.QtoField}`;
  if (!qtoGroups[key]) {
    qtoGroups[key] = {
      field:    item.json.QtoField,
      category: item.json.Category,
      rows:     []
    };
  }
  qtoGroups[key].rows.push(item.json);
});

function spearmanRank(values) {
  const sorted = values.map((v, i) => ({ val: v, idx: i }))
                       .sort((a, b) => a.val - b.val);
  const ranks = new Array(values.length);
  let i = 0;
  while (i < sorted.length) {
    let j = i;
    while (j < sorted.length && sorted[j].val === sorted[i].val) j++;
    const avgRank = (i + j + 1) / 2;
    for (let k = i; k < j; k++) ranks[sorted[k].idx] = avgRank;
    i = j;
  }
  return ranks;
}

function calcSRCC(ranksA, ranksB) {
  const n = ranksA.length;
  if (n < 3) return null;
  const dSquaredSum = ranksA.reduce((sum, rA, i) => sum + (rA - ranksB[i]) ** 2, 0);
  return 1 - (6 * dSquaredSum) / (n * (n * n - 1));
}

const srccResults = [];

for (const [, group] of Object.entries(qtoGroups)) {
  const { field, category, rows } = group;

  if (rows.length < 3) {
    srccResults.push({
      Category:     category,
      QtoField:     field,
      ElementCount: rows.length,
      SRCC:         null,
      RankStable:   false,
      Note:         'Too few elements for SRCC (need ≥ 3)'
    });
    continue;
  }

  const ranksA = spearmanRank(rows.map(r => r.Value_A));
  const ranksB = spearmanRank(rows.map(r => r.Value_B));
  const srcc   = calcSRCC(ranksA, ranksB);
  const srccR  = srcc !== null ? Math.round(srcc * 10000) / 10000 : null;

  let note = '';
  if      (srcc === null)  note = 'Could not compute';
  else if (srcc === 1)     note = 'Perfect rank agreement';
  else if (srcc >= 0.95)   note = 'Strong rank agreement';
  else if (srcc >= 0.80)   note = 'Moderate — risk rankings may differ';
  else                     note = 'Weak — significant rank instability';

  srccResults.push({
    Category:     category,
    QtoField:     field,
    ElementCount: rows.length,
    SRCC:         srccR,
    RankStable:   srcc !== null && srcc >= 0.95,
    Note:         note
  });
}

const scoredFields   = srccResults.filter(r => r.SRCC !== null);
const stableFields   = scoredFields.filter(r => r.RankStable);
const unstableFields = scoredFields.filter(r => !r.RankStable);

// ✅ Average SRCC — less strict than all-or-nothing
const avgSRCC = scoredFields.length > 0
  ? Math.round(scoredFields.reduce((s, r) => s + r.SRCC, 0) / scoredFields.length * 10000) / 10000
  : null;

const overallStable = avgSRCC !== null && avgSRCC >= 0.95;

let overallNote = '';
if      (scoredFields.length === 0) overallNote = 'No fields had enough data for SRCC';
else if (overallStable)             overallNote = 'Overall rank agreement is strong (avg SRCC ≥ 0.95)';
else if (unstableFields.length > 0) overallNote = `${unstableFields.length} field(s) have unstable rankings — review before using in risk model`;

// 1. SRCC summary
output.push({
  json: {
    _type:                'srcc_summary',
    total_fields_scored:  scoredFields.length,
    stable_fields:        stableFields.length,
    unstable_fields:      unstableFields.length,
    average_srcc:         avgSRCC,
    overall_rank_stable:  overallStable,
    overall_note:         overallNote,
    srcc_results:         srccResults
  }
});

// 2. Individual SRCC rows — easier for Excel/report export
srccResults.forEach(r => {
  output.push({ json: { _type: 'srcc_result', ...r } });
});

// 3. Pass everything except qto_comparison downstream
items.forEach(item => {
  if (item.json._type !== 'qto_comparison') {
    output.push(item);
  }
});

return output;

