function materialModifier(material) {
  if (!material || typeof material !== 'string') return 0;
  const m = material.toLowerCase();
  if (m.includes('wood')   || m.includes('timber'))         return  0.15;
  if (m.includes('masonry')|| m.includes('brick'))          return  0.10;
  if (m.includes('glass'))                                  return  0.10;
  if (m.includes('steel')  || m.includes('metal'))          return  0.05;
  if (m.includes('concrete')|| m.includes('reinforced'))    return -0.05;
  return 0;
}

