  const candidates = [
    json['[BaseQuantities] GrossVolume'],
    json['[BaseQuantities].GrossVolume'],
    json['[BaseQuantities] GrossArea'],
    json['[BaseQuantities].GrossArea'],
    json['[BaseQuantities] NetFloorArea'],
    json['[BaseQuantities].NetFloorArea'],
    json['[Qto_SpaceBaseQuantities] NetFloorArea'],
    json['[Dimensions] Volume'],
    json['[Dimensions] Area'],
  ];
  for (const v of candidates) {
    const f = parseFloat(v);
    if (!isNaN(f) && f > 0) return f;
  }
  return 0;
}

const targets   = items.filter(i => i.json._type === 'risk_likelihood');
const extents   = targets.map(i => readExtent(i.json));

// ✅ Normalize per Category — prevents large slabs from dwarfing small columns
const maxExtentByCategory = {};
targets.forEach((item, i) => {
  const cat = item.json.Category || 'Unknown';
  if (!maxExtentByCategory[cat] || extents[i] > maxExtentByCategory[cat]) {
    maxExtentByCategory[cat] = extents[i];
  }
});

// Global max as fallback
const maxExtent = extents.length > 0 ? Math.max(...extents) : 1;

const extentMap = new Map();
targets.forEach((item, i) => {
  extentMap.set(item.json.GlobalId, extents[i]);
});

return items.map(item => {
  if (item.json._type !== 'risk_likelihood') return item;

  const json    = item.json;
  const ifcType = json.Category || '';
  const domain  = json.domain   || json.ifc_domain || 'Building';
  const extent  = extentMap.get(json.GlobalId) ?? 0;

  if (!ifcType) {
    return {
      json: {
        ...json,
        _type:             'risk_consequence',
        consequence_score: DEFAULT_CONSEQUENCE,
        criticality_base:  DEFAULT_CRITICALITY,
        qto_extent:        extent,
      }
    };
  }

  const { table, warn } = selectTable(domain);
  const criticalityBase = table[ifcType] !== undefined
    ? table[ifcType]
    : DEFAULT_CRITICALITY;

  // ✅ Normalize within same Category — columns vs slabs compared fairly
  const catMax           = maxExtentByCategory[ifcType] || maxExtent || 1;
  const normalizedExtent = catMax > 0 ? extent / catMax : 0;
  const consequence      = criticalityBase * (0.7 + 0.3 * normalizedExtent);

  return {
    json: {
      ...json,
      _type:             'risk_consequence',
      consequence_score: Math.round(consequence * 10000) / 10000,
      criticality_base:  criticalityBase,
      qto_extent:        extent,
      normalized_extent: Math.round(normalizedExtent * 10000) / 10000,
      ...(warn && { domain_warning: true }),
    }
  };
});

const items = $input.all();

// α (alpha) — uncertainty sensitivity constant. Fixed and version-controlled
// via Config, not inferred per-model, so bound widths stay comparable and
// reproducible across different runs (see Config: alpha, default 0.55).
const ALPHA = $node['0.1: Config']?.json?.alpha ?? 0.5;

const output = [];

for (const item of items) {

  if (item.json._type !== 'risk_consequence') {
    output.push(item);
    continue;
  }

  const json = item.json;

  const L   = json.likelihood_score  || 0;
  const C   = json.consequence_score || 0;
  const bqi = typeof json.bqi_score === 'number' ? json.bqi_score : 0;

  // R_raw = L × C — deterministic base estimate, independent of data quality
  const R_raw = Math.min(1, Math.max(0, L * C));

  // Uncertainty widening — grows toward α as BQI drops to 0,
  // vanishes to 0 as BQI reaches 1 (cone converges, per thesis diagram)
  const widening = ALPHA * (1 - bqi);

  // R_adj = R_raw × (1 + α × (1 − BQI))  — thesis formula (slide 7).
  // Conservative/upper-leaning adjusted estimate — the headline score.
  const R_adj   = Math.min(1, R_raw * (1 + widening));
  const R_upper = R_adj;
  const R_lower = Math.max(0, R_raw * (1 - widening));

  output.push({
    json: {
      ...json,
      _type:             'risk_element',
      risk_score:         R_adj,   // kept as 'risk_score' — Block 5 compatibility
      risk_score_raw:     R_raw,
      risk_score_lower:   R_lower,
      risk_score_upper:   R_upper,
      uncertainty_band:   (R_upper - R_lower),
      alpha_used:         ALPHA,
      bqi_used:           bqi,
    }
  });
}

return output;

// =============================================================================
// Node 2.6 · Filter Analysis Elements
//
// Purpose:
// Removes records that are not required for downstream civil infrastructure
// analysis, leaving only relevant physical IFC elements.
//
// Excluded:
//   • Metadata records
//   • Spatial hierarchy entities generated during IFC extraction
//   • IFC categories intentionally excluded from the analysis
//
// Notes:
// - Spatial hierarchy objects are primarily filtered using "_type".
// - The category list below acts as a safeguard in case spatial objects are
//   received as regular elements or if additional non-structural objects
//   should be excluded.
// =============================================================================

// -----------------------------------------------------------------------------
// IFC categories excluded from analysis.
//
// Spatial hierarchy objects are included as a fallback safeguard.
// IfcFurniture is intentionally excluded because it is outside the scope of
// civil infrastructure risk assessment.
//
// Extend this list if additional categories should be ignored.
// -----------------------------------------------------------------------------
const excludedCategories = new Set([
  // Spatial hierarchy (fallback)
  'IfcProject',
  'IfcSite',
  'IfcBuilding',
  'IfcBuildingStorey',
  'IfcSpace',

  // Non-structural objects
  'IfcFurniture'
]);

return $input.all().filter(item => {
  const el = item.json;

  // Remove project-level metadata
  if (el._type === 'metadata') return false;

  // Remove spatial hierarchy entities produced by the extraction node.
  // This automatically covers IFC4 and IFC4X3 entities such as:
  //   - IfcProject
  //   - IfcSite
  //   - IfcBuilding
  //   - IfcFacility
  //   - IfcBridge
  //   - IfcRoad
  //   - IfcRailway
  if (el._type === 'spatial_entity') return false;

  // Remove categories intentionally excluded from the analysis
  if (excludedCategories.has(el.Category)) return false;

  // Keep all remaining physical IFC elements
  return true;
});

