// ---- helpers ---------------------------------------------------------------
function plural(n, word) { return `${n} ${word}${n === 1 ? '' : 's'}`; }
function confColor(conf)  { return conf === 'high' ? '#009a44' : conf === 'medium' ? '#ffa726' : '#dc3545'; }
function verdictColor(v)  { return v === 'PASS' ? '#009a44' : v === 'REVIEW' ? '#ffa726' : v === 'FAIL' ? '#dc3545' : '#999'; }
function riskColor(label) { return label === 'High' ? '#dc3545' : label === 'Medium' ? '#ffa726' : '#66bb6a'; }
function bqiBar(score) {
  const pct = Math.round((score || 0) * 100);
  const col = score >= 0.85 ? '#009a44' : score >= 0.60 ? '#ffa726' : '#dc3545'; // aligned with 3.4 confidence bands
  return `<div style="background:#e0e0e0;height:6px;border-radius:3px;width:80px;display:inline-block;vertical-align:middle;margin-left:8px"><div style="height:100%;width:${pct}%;background:${col};border-radius:3px"></div></div>`;
}

// ============================================================================
// SVG / CSS CHART BUILDERS
// ============================================================================

// 1) Risk-distribution donut ------------------------------------------------
function donutSvg(vals, colors) {
  const total = vals.reduce((a, b) => a + (+b || 0), 0);
  const r = 52, cx = 70, cy = 70, C = 2 * Math.PI * r;
  let off = 0, arcs = '';
  if (total > 0) {
    vals.forEach((v, i) => {
      const len = (v / total) * C;
      if (len > 0) {
        arcs += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${colors[i]}" stroke-width="18" stroke-linecap="butt" stroke-dasharray="${len.toFixed(3)} ${(C - len).toFixed(3)}" stroke-dashoffset="${(-off).toFixed(3)}" transform="rotate(-90 ${cx} ${cy})"></circle>`;
      }
      off += len;
    });
  } else {
    arcs = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#e0e0e0" stroke-width="18"></circle>`;
  }
  return `<svg width="140" height="140" viewBox="0 0 140 140" style="display:block;margin:0 auto">${arcs}<text x="70" y="66" text-anchor="middle" font-size="26" font-weight="700" fill="#2e2e38" font-family="Arial,sans-serif">${total}</text><text x="70" y="84" text-anchor="middle" font-size="9" fill="#999" font-family="Arial,sans-serif">ELEMENTS</text></svg>`;
}
function donutLegend(pairs) {
  return `<div style="display:flex;justify-content:center;gap:16px;margin-top:10px;font-size:11px">` +
    pairs.map(p => `<span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:10px;border-radius:50%;background:${p.color};display:inline-block"></span>${p.label} (${p.value})</span>`).join('') +
    `</div>`;
}

// 2) Horizontal bar rows (used by the SRCC chart) ----------------------------
function hbars(rows) {
  return rows.map(r => `<div style="margin-bottom:11px">
    <div style="display:flex;justify-content:space-between;font-size:11px;color:#4a4a4a;margin-bottom:3px">
      <span>${r.label}</span><span style="font-weight:600;color:${r.color}">${r.text}</span>
    </div>
    <div style="background:#e0e0e0;height:10px;border-radius:5px;overflow:hidden">
      <div style="width:${Math.max(0, Math.min(100, r.pct))}%;height:100%;background:${r.color};border-radius:5px"></div>
    </div>
  </div>`).join('');
}

// 3) Radar — BQI dimensions, Pipeline A vs B ---------------------------------
function radarSvg() {
  if (!dimsA && !dimsB) return '<p style="color:#999;font-size:12px">Per-pipeline dimension data unavailable. Re-run the workflow with the updated Node 3.4.</p>';
  const axes = ['D1_completeness', 'D2_validity', 'D3_qto_coverage', 'D4_qto_agreement'];
  const labels = ['D1 Compl.', 'D2 Valid.', 'D3 QTO Cov.', 'D4 Agree.'];
  const cx = 120, cy = 110, R = 78, n = axes.length;
  const pt = (i, v) => {
    const a = -Math.PI / 2 + i * 2 * Math.PI / n;
    return `${(cx + R * v * Math.cos(a)).toFixed(3)},${(cy + R * v * Math.sin(a)).toFixed(3)}`;
  };
  let s = `<svg width="240" height="230" viewBox="0 0 240 230" xmlns="http://www.w3.org/2000/svg" style="display:block;margin:0 auto">`;
  [0.25, 0.5, 0.75, 1].forEach(r => {
    s += `<polygon points="${axes.map((_, i) => pt(i, r)).join(' ')}" fill="none" stroke="#e0e0e0"/>`;
  });
  axes.forEach((_, i) => {
    const [x, y] = pt(i, 1).split(',');
    s += `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="#e0e0e0"/>`;
  });
  const series = (d, col) => {
    if (!d) return;
    s += `<polygon points="${axes.map((k, i) => pt(i, d[k] || 0)).join(' ')}" fill="${col}" fill-opacity="0.20" stroke="${col}" stroke-width="2"/>`;
  };
  series(dimsA, '#0061a0');
  series(dimsB, '#009a44');
  labels.forEach((lb, i) => {
    const [x, y] = pt(i, 1.22).split(',');
    s += `<text x="${x}" y="${y}" font-size="10" fill="#555" text-anchor="middle" font-family="Arial,sans-serif">${lb}</text>`;
  });
  s += `</svg><div style="font-size:11px;color:#666;text-align:center">
    ${dimsA ? '<span style="color:#0061a0">&#9632;</span> Pipeline A (DDC)&nbsp;&nbsp;' : ''}
    ${dimsB ? '<span style="color:#009a44">&#9632;</span> Pipeline B (IfcOpenShell)' : ''}
    <br>D4 measures cross-pipeline agreement and applies to both series</div>`;
  return s;
}

