  <td style="padding:8px 12px;text-align:center;font-weight:700">${((weights[wKey] || 0) * (score || 0)).toFixed(3)}</td>
</tr>`).join('') + `<tr style="border-top:2px solid #ccc">
  <td colspan="3" style="padding:8px 12px;font-weight:700">Model BQI (&Sigma; weight &times; score)</td>
  <td style="padding:8px 12px;text-align:center;font-weight:800">${modelBQI.toFixed(3)}</td></tr>`;

// Fallback (only used if dim averages are missing): weights-only rows
