).join('');

// 5) Scatter — top-10 risk score vs BQI score --------------------------------
function scatterSvg(points) {
  const W = 680, H = 240, padL = 48, padR = 20, padT = 16, padB = 42;
  const iw = W - padL - padR, ih = H - padT - padB;
  const maxY = Math.max(0.01, ...points.map(p => p.y)) * 1.15;
  const sx = x => padL + Math.max(0, Math.min(1, x)) * iw;
  const sy = y => padT + ih - (y / maxY) * ih;
  let g = '';
  for (let k = 0; k <= 4; k++) {
    const yy = padT + ih - (k / 4) * ih;
    g += `<line x1="${padL}" y1="${yy}" x2="${padL + iw}" y2="${yy}" stroke="#eee"></line>`;
    g += `<text x="${padL - 6}" y="${yy + 3}" text-anchor="end" font-size="9" fill="#999" font-family="Arial,sans-serif">${(maxY * k / 4).toFixed(3)}</text>`;
  }
  [0, 0.25, 0.5, 0.75, 1].forEach(t => {
    const xx = sx(t);
    g += `<line x1="${xx}" y1="${padT}" x2="${xx}" y2="${padT + ih}" stroke="#f5f5f5"></line>`;
    g += `<text x="${xx}" y="${padT + ih + 16}" text-anchor="middle" font-size="9" fill="#999" font-family="Arial,sans-serif">${t}</text>`;
  });
  g += `<text x="${padL + iw / 2}" y="${H - 4}" text-anchor="middle" font-size="10" fill="#696969" font-family="Arial,sans-serif">BQI Score (0 = poor, 1 = complete)</text>`;
  g += `<text x="12" y="${padT + ih / 2}" text-anchor="middle" font-size="10" fill="#696969" font-family="Arial,sans-serif" transform="rotate(-90 12 ${padT + ih / 2})">Risk Score</text>`;
  points.forEach(p => {
    g += `<circle cx="${sx(p.x).toFixed(3)}" cy="${sy(p.y).toFixed(3)}" r="6" fill="${p.color}" fill-opacity="0.85" stroke="#fff" stroke-width="1.5"></circle>`;
  });
  if (!points.length) {
    g += `<text x="${W / 2}" y="${H / 2}" text-anchor="middle" font-size="12" fill="#999" font-family="Arial,sans-serif">No risk elements scored yet</text>`;
  }
  return `<svg width="100%" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" style="display:block">${g}</svg>`;
}

// 6) Uncertainty band — R_lower / R_raw / R_adj for the top-ranked element ----
function riskBandHtml() {
  const t = top10[0]; if (!t) return '';
  const j = t.json, pct = v => Math.min(100, Math.max(0, (v || 0) * 100)).toFixed(3);
  const lo = pct(j.risk_score_lower), raw = pct(j.risk_score_raw), adj = pct(j.risk_score);
  return `<div style="margin:14px 0">
    <div style="font-size:11px;color:#666;margin-bottom:6px">Top-ranked element (${(j.GlobalId || '').slice(0, 12)} · ${j.Category || ''}): R_lower, R_raw, and R_adj on a 0 to 1 scale</div>
    <div style="position:relative;height:30px;background:#f0f2f5;border-radius:6px">
      ${[25, 50, 75].map(g => `<div style="position:absolute;top:0;height:100%;left:${g}%;width:1px;background:#dde3ea"></div>`).join('')}
      <div style="position:absolute;left:${lo}%;width:${(adj - lo).toFixed(3)}%;height:100%;background:#ffa72622;border:1px solid #ffa72666;border-radius:4px"></div>
      <div style="position:absolute;top:0;height:100%;left:${lo}%;width:2px;background:#999"></div>
      <div style="position:absolute;top:0;height:100%;left:${raw}%;width:2px;background:#555;border-left:1px dashed #555"></div>
      <div style="position:absolute;top:0;height:100%;left:${adj}%;width:3px;background:#dc3545"></div>
    </div>
    <div style="display:flex;justify-content:space-between;font-size:10px;color:#999;margin-top:2px">
      <span>0</span><span>0.25</span><span>0.50</span><span>0.75</span><span>1.00</span>
    </div>
    <div style="font-size:11px;color:#475569;margin-top:10px;line-height:2">
      <div><span style="color:#555;font-weight:700">&#124;</span> <b>R_raw</b> = L &times; C = ${(j.risk_score_raw || 0).toFixed(3)} (deterministic base, dashed marker)</div>
      <div><span style="color:#dc3545;font-weight:700">&#124;</span> <b>R_adj</b> = R_raw &times; (1 <b>+</b> &alpha;(1 &minus; BQI)) = ${(j.risk_score || 0).toFixed(3)} (upper limit, red marker; used for the ranking)</div>
      <div><span style="color:#999;font-weight:700">&#124;</span> <b>R_lower</b> = R_raw &times; (1 <b>&minus;</b> &alpha;(1 &minus; BQI)) = ${(j.risk_score_lower || 0).toFixed(3)} (lower limit, grey marker)</div>
      <div><b>Band width</b> = R_adj &minus; R_lower = ${(j.uncertainty_band || 0).toFixed(3)}, with &alpha; = ${(j.alpha_used ?? 0.55).toFixed(3)} and BQI<sub>element</sub> = ${(j.bqi_used ?? 0).toFixed(3)}</div>
    </div></div>`;
}

// ---- Overall screening verdict ----------------------------------------------
// Combines the two orthogonal checks: data DEPTH (model BQI confidence) and
// element BREADTH (cross-pipeline coverage). Deterministic rule, printed with
// its reasons so the verdict is auditable.
let overallVerdict = 'RELIABLE', overallColor = '#009a44';
const overallReasons = [];
if (modelConf === 'low')          overallReasons.push('model BQI confidence is LOW');
if (coverageVerdict === 'FAIL')   overallReasons.push('element coverage verdict is FAIL');
if (modelConf === 'medium')       overallReasons.push('model BQI confidence is MEDIUM');
if (coverageVerdict === 'REVIEW') overallReasons.push('element coverage needs review');
if (highRisk > 0)                 overallReasons.push(plural(highRisk, 'element') + ' screened as high risk');
if (modelConf === 'low' || coverageVerdict === 'FAIL') {
  overallVerdict = 'DATA UNRELIABLE'; overallColor = '#dc3545';
} else if (modelConf === 'medium' || coverageVerdict === 'REVIEW' || highRisk > 0) {
  overallVerdict = 'USE WITH CAUTION'; overallColor = '#ffa726';
}

// ---- build the chart markup ------------------------------------------------
const distDonut = donutSvg([highRisk, medRisk, lowRisk], ['#dc3545', '#ffa726', '#66bb6a']) +
  donutLegend([
    { label: 'High',   value: highRisk, color: '#dc3545' },
    { label: 'Medium', value: medRisk,  color: '#ffa726' },
    { label: 'Low',    value: lowRisk,  color: '#66bb6a' },
  ]);

const srccBars = srccResults.length
  ? hbars(srccResults.slice(0, 8).map(r => {
      const s = +(r.SRCC || 0);
      const col = s >= 0.95 ? '#009a44' : s >= 0.80 ? '#ffa726' : '#dc3545';
      const field = `${(r.QtoField || '').replace('[Qto_', '').replace(']', ' ')}`.slice(0, 24) || (r.Category || '-');
      return { label: field, pct: Math.round(s * 100), text: s.toFixed(3), color: col };
    }))
  : `<p style="color:#999;font-size:12px;text-align:center;padding:20px">SRCC not yet computed for this run</p>`;

const scatterChart = scatterSvg(top10.map(i => ({
  x: +(i.json.bqi_score || 0),
  y: +(i.json.risk_score || 0),
  color: riskColor(i.json.risk_label || 'Low'),
})));

// ---- table rows ------------------------------------------------------------
const riskRows = top10.map((item, idx) => {
  const d = item.json;
  const label = d.risk_label || 'Low';
  return `<tr>
    <td>${idx + 1}</td>
    <td style="font-family:monospace;font-size:11px">${(d.GlobalId || '-').slice(0, 16)}</td>
    <td>${d.Category || '-'}</td>
    <td>${d.zone || '-'}</td>
    <td>${(+(d.bqi_score || 0)).toFixed(3)} ${bqiBar(d.bqi_score)}</td>
    <td>${d.bqi_confidence || '-'}</td>
    <td>${(+(d.likelihood_score  || 0)).toFixed(3)}</td>
    <td>${(+(d.consequence_score || 0)).toFixed(3)}</td>
    <td><strong>${(+(d.risk_score || 0)).toFixed(3)}</strong></td>
    <td><span style="display:inline-block;padding:2px 8px;background:${riskColor(label)};color:white;font-size:11px;font-weight:600;border-radius:2px">${label.toUpperCase()}</span></td>
  </tr>`;
}).join('') || `<tr><td colspan="10" style="text-align:center;color:#999;padding:20px">No risk elements scored yet</td></tr>`;

const srccRows = srccResults.length
  ? srccResults.slice(0, 8).map(r => {
      const srcc  = +(r.SRCC || 0).toFixed(3);
      const label = srcc >= 0.95 ? 'Strong' : srcc >= 0.80 ? 'Moderate' : 'Weak';
      const col   = srcc >= 0.95 ? '#009a44' : srcc >= 0.80 ? '#ffa726' : '#dc3545';
      return `<tr>
        <td style="font-size:11px;font-family:monospace">${(r.QtoField || '').replace('[Qto_', '').replace(']', ' ').slice(0, 28)}</td>
        <td>${srcc}</td>
        <td>${r.ElementCount || '-'}</td>
        <td><span style="color:${col};font-weight:600">${label}</span></td>
        <td style="font-size:11px;color:#696969">${r.Note || ''}</td>
      </tr>`;
    }).join('')
  : `<tr><td colspan="5" style="text-align:center;color:#999;padding:16px">SRCC not yet computed for this run</td></tr>`;

// ---- D1/D2/D3 drilldowns: which fields are actually missing or invalid -----
// Aggregated from the per-element lists produced by Node 3.4
// (missing_properties -> D1, invalid_properties -> D2, missing_qto -> D3).
function topCounts(field) {
  const counts = {};
  for (const el of riskElements) {
    for (const p of (el.json[field] || [])) counts[p] = (counts[p] || 0) + 1;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
}
function findingsTable(rows, emptyMsg) {
  if (!rows.length) return `<p style="color:#999;font-size:12px;padding:12px 16px">${emptyMsg}</p>`;
  return `<table><thead><tr><th>Field</th><th style="text-align:center">Elements affected</th></tr></thead><tbody>` +
    rows.map(([k, v]) => `<tr><td style="font-family:monospace;font-size:11px">${k}</td><td style="text-align:center">${v}</td></tr>`).join('') +
    `</tbody></table>`;
}
const d1Table = findingsTable(topCounts('missing_properties'), 'No required properties missing');
const d2Table = findingsTable(topCounts('invalid_properties'), 'No invalid property values found');
const d3Table = findingsTable(topCounts('missing_qto'),        'No expected quantity fields missing');

// ---- Summary text: AI if available, otherwise a recommended-action note ----
// Deliberately does NOT repeat the banner or KPI numbers. It answers the one
// question those layers leave open: what should the reader do next?
let summarySource = execSummary ? 'ai' : 'rule';
let execSummaryText = execSummary;
let execSummaryParas = execSummary ? [execSummary] : [];
if (!execSummaryText && riskElements.length > 0) {
  const s = [];
  if (overallVerdict === 'DATA UNRELIABLE') {
    s.push('Improve the model data before acting on the risk ranking: with data this sparse, the scores mainly reflect missing information rather than real risk.');
  } else if (overallVerdict === 'USE WITH CAUTION') {
    s.push('The ranking is usable, but verify flagged elements against the source model before committing decisions.');
  } else {
    s.push('Data quality is sufficient to act on the ranking directly.');
  }
  const t = top10[0];
  if (t) {
    s.push(`Start with the top-ranked element (${t.json.Category || 'unknown type'}, ${(t.json.GlobalId || '').slice(0, 8)}…): R_adj ${(t.json.risk_score || 0).toFixed(3)} with an uncertainty band of ${(t.json.uncertainty_band || 0).toFixed(3)}. ${(t.json.uncertainty_band || 0) > 0.15 ? 'The wide band means better data would sharpen this score considerably' : 'The narrow band means this score is driven by the element itself, not by data gaps'}.`);
  }
  const md1 = topCounts('missing_properties')[0];
  const md3 = topCounts('missing_qto')[0];
  if (md1 && md3) {
    s.push(`For the fastest data improvement, add ${md1[0]} (missing on ${plural(md1[1], 'element')}) and the quantity ${md3[0]} (missing on ${plural(md3[1], 'element')}). See Section 2 for the full repair list.`);
  } else if (md1) {
    s.push(`For the fastest data improvement, add ${md1[0]} (missing on ${plural(md1[1], 'element')}). See Section 2 for the full repair list.`);
  } else if (md3) {
    s.push(`For the fastest data improvement, add the quantity ${md3[0]} (missing on ${plural(md3[1], 'element')}). See Section 2 for the full repair list.`);
  }
  execSummaryText = s.join(' ');   // kept for report_summary compatibility
  execSummaryParas = s;            // rendered as one <p> per sentence group
}

