          </div>
          <div class="severity-box" style="background:#fff8e1;border-color:#ffe08a">
            <div style="font-size:28px;font-weight:300;color:#ffa726">${severityBreakdown.needs_review}</div>
            <div style="font-size:11px;text-transform:uppercase;font-weight:600;color:#ffa726;margin-top:4px">Needs Review</div>
            <div style="font-size:11px;color:#999;margin-top:4px">${sevCaption(sevTypes.needs_review)}</div>
          </div>
          <div class="severity-box" style="background:#f0faf4;border-color:#b7dfca">
            <div style="font-size:28px;font-weight:300;color:#009a44">${severityBreakdown.probably_harmless}</div>
            <div style="font-size:11px;text-transform:uppercase;font-weight:600;color:#009a44;margin-top:4px">Probably Harmless</div>
            <div style="font-size:11px;color:#999;margin-top:4px">${sevCaption(sevTypes.probably_harmless)}</div>
          </div>
        </div>
        <div style="margin-top:16px;font-size:12px;color:#696969;text-align:center">
          Total missing elements: <strong>${missingTotal}</strong> &nbsp;|&nbsp;
          Verdict: <strong style="color:${verdictColor(coverageVerdict)}">${coverageVerdict}</strong> &nbsp;|&nbsp;
          Coverage risk level: <strong>${coverageRisk}</strong>
        </div>
      </div>
    </div>
  </div>

  <div class="footer">
    <p><strong>Uncertainty-Aware Risk Screening from Imperfect BIM</strong> &nbsp;|&nbsp; EMJM NORISK &nbsp;|&nbsp; ${new Date().toLocaleString()}</p>
    <p style="margin-top:6px">Pipeline A: DDC Converter &nbsp;|&nbsp; Pipeline B: IfcOpenShell &nbsp;|&nbsp; Orchestrated via n8n</p>
  </div>

</div>
</body>
</html>`;

// ---- RETURN -----------------------------------------------------------------
const ts    = new Date();
const pad   = n => String(n).padStart(2, '0');
const stamp = `${ts.getFullYear()}-${pad(ts.getMonth() + 1)}-${pad(ts.getDate())}-${pad(ts.getHours())}-${pad(ts.getMinutes())}`;

return [
  {
    json: {
      _type:     'report_html',
      html:      html,
      filename:  `risk-register-${fileTag}-${stamp}.html`,
      timestamp: new Date().toISOString(),
    }
  },
  {
    json: {
      _type:               'report_summary',
      project:             projectFileName,
      timestamp:           new Date().toISOString(),
      model_bqi:           modelBQI,
      model_confidence:    modelConf,
      total_elements:      totalScored,
      coverage_pct:        coveragePct,
      coverage_verdict:    coverageVerdict,
      coverage_risk:       coverageRisk,
      high_risk:           highRisk,
      medium_risk:         medRisk,
      low_risk:            lowRisk,
      avg_srcc:            avgSRCC,
      overall_rank_stable: overallRankStable,
      ai_summary_included: !!execSummary,
      // Run provenance — all three derived from the same trimmed test, so the
      // flag and the recorded sources can never contradict each other.
      dual_file_mode:      _isDual,
      pipeline_a_source:   _sourceA || null,
      pipeline_b_source:   _sourceB || _sourceA || null,
    }
  }
];

const items = $input.all();

const meta = items.find(i => i.json._type === 'metadata');
const schemaDetected = meta?.json?.schema || 'unknown';
const metaAllKeys = meta ? Object.keys(meta.json) : [];   // ← new: see everything metadata actually carries

const sample = items.find(i => i.json.ifc_domain);
const domainDetected = sample?.json?.ifc_domain || 'not set';

const byType = {};
for (const item of items) {
  const el = item.json;
  if (el._type !== 'element' && el._type !== 'spatial_entity') continue;
  const type = el.Category || 'Unknown';
  const key = `${el._type}::${type}`;
  if (!byType[key]) byType[key] = new Set();
  Object.keys(el)
    .filter(k => k.startsWith('['))
    .forEach(k => byType[key].add(k));
}

const output = [
  {
    json: {
      _diagnostic: 'schema_domain_summary',
      schema_detected: schemaDetected,
      domain_detected: domainDetected,
      metadata_raw: meta ? meta.json : null,       // ← new: full metadata object, unfiltered
      metadata_keys: metaAllKeys                     // ← new: just the key names, easy to scan
    }
  }
];

Object.entries(byType).forEach(([key, keys]) => {
  const [entityType, category] = key.split('::');
  output.push({ json: { entity_type: entityType, Category: category, keys: [...keys].sort() } });
});

return output;

const items = $input.all();

const byType = {};
for (const item of items) {
  const el = item.json;
  if (el._type !== 'element') continue;
  const type = el.Category || 'Unknown';
  if (!byType[type]) byType[type] = { count: 0, keys: new Set() };
  byType[type].count++;
  Object.keys(el)
    .filter(k => k.startsWith('['))
    .forEach(k => byType[type].keys.add(k));
}

const totalItems = items.length;
const totalElements = items.filter(i => i.json._type === 'element').length;

return [
  { json: { _diagnostic: 'pipeline_a_totals', total_items: totalItems,
            total_elements: totalElements, categories: Object.keys(byType).length } },
  ...Object.entries(byType).map(([type, data]) => ({
    json: { Category: type, element_count: data.count, keys: [...data.keys].sort() }
  })),
];

return Object.entries(byType).map(([type, data]) => ({
  json: {
    Category: type,
    element_count: data.count,
    keys: [...data.keys].sort()
  }
}));

// HTML to Binary — select report_html explicitly, get project_file from Config
const reportItem = $input.all().find(i => i.json._type === 'report_html');

if (!reportItem || typeof reportItem.json.html !== 'string') {
  throw new Error('No report_html item found — check Node 5.6 output');
}

const html        = reportItem.json.html;
const projectFile = $node['0.1: Config'].json.project_file;
const fileName    = reportItem.json.filename
  || `IFC_Risk_Register_${new Date().toISOString().slice(0, 10)}.html`;

return [{
  json: {
    fileName:     fileName,
    project_file: projectFile,
  },
  binary: {
    data: {
      data:          Buffer.from(html, 'utf8').toString('base64'),
      mimeType:      'text/html',
      fileName:      fileName,
      fileExtension: 'html',
    }
  }
}];

// 5.8: Prepare HTML Path — writes to Config output_dir, falls back to IFC folder
const fileName    = $input.first().json.fileName;
const projectFile = $input.first().json.project_file || '';

const configured = $node['0.1: Config'].json.output_dir;

let directory;
if (configured && configured.trim() !== '') {
  directory = configured.replace(/[\\/]+$/, '');   // strip trailing slash
} else {
  const lastSlash = Math.max(projectFile.lastIndexOf('\\'), projectFile.lastIndexOf('/'));
  directory = projectFile.substring(0, lastSlash);
}

const fullPath = `${directory}\\${fileName}`;

return [{
  json: {
    html_filename: fileName,
    full_path:     fullPath,
    directory:     directory,
    project_file:  projectFile,
  },
  binary: $input.first().binary,
}];

// ============================================================================
// 5.6: Sensitivity Analysis — dead-end export node after 4.5
// ----------------------------------------------------------------------------
// Exports the per-element inputs required by the offline analysis scripts
// (sensitivity_analysis.py, alpha_characterization.py, fault_analysis.py):
// the four BQI dimension scores plus the likelihood and consequence proxies.
// Values are exported at full precision; rounding happens only at display
// time in the HTML report, never on the computation path.
//
// FILE NAMING CONTRACT
//   Baseline run     sensitivity-<model>.json
//   Single-file run  sensitivity-<model>__F4-r25-s42_PIPELINE-B-ONLY.json
//   Dual-file run    sensitivity-<model>__F4-r25-s42_PIPELINE-B-ONLY_DUALFILE.json
//
// The model name is taken from project_file_b when that field is set, and from
// project_file otherwise, so a fault variant read by Pipeline B alone never
// writes over the baseline export that fault_analysis.py computes deltas
// against. The _DUALFILE marker is required because fault_injection.py names
// every F4 and F6 variant with the _PIPELINE-B-ONLY suffix regardless of how
// it is later fed: without the marker, the single-file and dual-file runs of
// the same fault and severity resolve to the same filename and one silently
// overwrites the other.
//
// Downstream: connect a "Write Binary File" node
//   File Name (expression):  {{ $json.full_path }}
//   Property Name:           data
// ============================================================================

const fields = [
  'GlobalId', 'Category',
  'score_completeness', 'score_validity',
  'score_qto_coverage', 'score_qto_agreement',
  'likelihood_score', 'consequence_score',
];

const rows = $input.all()
  .filter(i => i.json._type === 'risk_element')
  .map(i => Object.fromEntries(fields.map(f => [f, i.json[f]])));

// ---- Run configuration -----------------------------------------------------
// project_file_b is trimmed before testing: a Set node that leaves a stray
// space would otherwise make Boolean() true and turn every run into a
// dual-file run without any visible sign.
const cfg      = $node['0.1: Config'].json;
const sourceB  = String(cfg.project_file_b || '').trim();
const sourceA  = String(cfg.project_file   || '').trim();
const isDual   = sourceB.length > 0;

const projectFile = isDual ? sourceB : (sourceA || 'unknown-model');

const baseName = projectFile
  .split('\\').pop()
  .split('/').pop()
  .replace(/\.[^/.]+$/, '');

const modelName = baseName + (isDual ? '_DUALFILE' : '');

// ---- Output path -----------------------------------------------------------
const outputDir = String(cfg.output_dir || 'C:\\temp').replace(/[\\/]+$/, '');
const fileName  = `sensitivity-${modelName}.json`;
const fullPath  = `${outputDir}\\${fileName}`;

// ---- Guard: an empty export means nothing reached this node ----------------
// Without this, a broken upstream branch produces a valid but empty JSON file
// that the analysis scripts skip with a one-line message, which is easy to
// miss across a 130-run campaign.
if (rows.length === 0) {
  throw new Error(
    `5.6 Sensitivity Analysis: no risk_element items received for ${baseName}. ` +
    `Check that Block 4 completed and that the typed-item filter is intact.`
  );
}

return [{
  json: {
    model:             modelName,
    count:             rows.length,
    full_path:         fullPath,
    // Run provenance — recorded in the export so the configuration of every
    // run is visible in its own output rather than inferred from the machine.
    dual_file_mode:    isDual,
    pipeline_a_source: sourceA || null,
    pipeline_b_source: sourceB || sourceA || null,
  },
  binary: {
    data: {
      data:          Buffer.from(JSON.stringify(rows, null, 1)).toString('base64'),
      mimeType:      'application/json',
      fileName:      fileName,
      fileExtension: 'json',
    }
  }
}];


// ============================================================================
// PATCH FOR 5.1: Generate HTML — traceability, not overwrite
// ----------------------------------------------------------------------------
// CORRECTION: an earlier version of this note claimed a dual-file run would
// overwrite the baseline report. It will not. The report filename carries a
// timestamp down to the minute:
//
//     filename: `risk-register-${projectFileName}-${stamp}.html`
//
// so every run writes a uniquely named file and nothing is lost.
//
// The remaining issue is labelling. projectFileName comes from project_file
// alone. For single-file fault runs that is fine, because project_file holds
// the variant and the fault tag lands in the filename. But on the six
// dual-file runs project_file holds the BASELINE, so the report is named
//
//     risk-register-IFC4-Building-Architecture-2026-08-05-14-32.html
//
// with nothing indicating it was the dual-file F4 run at 10% severity. Among
// hundreds of timestamped files those six look like ordinary baseline
// reports, and the only way to tell is to open them.
//
// Insert after the projectFileName block (around line 24):
//
//     const _cfg     = $node['0.1: Config'].json;
//     const _sourceB = String(_cfg.project_file_b || '').trim();
//     const _isDual  = _sourceB.length > 0;
//     const fileTag  = projectFileName + (_isDual ? '_DUALFILE' : '');
//
// Then change two lines:
//
//     // ~line 641
//     filename: `risk-register-${fileTag}-${stamp}.html`,
//
//     // ~line 664 — must use the same test as 5.6 above
//     dual_file_mode: _isDual,        // was: Boolean(cfg.project_file_b)
//
// projectFileName itself is left alone, so the report title and the
// "Project:" line stay clean and keep naming what Pipeline A read. Only the
// filename carries the marker.
//
// The second line matters as much as the first. 5.1 still uses
// Boolean(project_file_b) while 5.6 uses String(...).trim(). If that field
// ever held a single space, 5.1 would report dual_file_mode: true while 5.6
// treated the same run as single-file — two artefacts from one run
// contradicting each other, with no way to tell which was right.
// ============================================================================

const all       = $input.all();
const others    = all.filter(i => i.json._type !== 'risk_element');
const riskItems = all.filter(i => i.json._type === 'risk_element');

riskItems.sort((a, b) => (b.json.risk_score || 0) - (a.json.risk_score || 0));

const scores = riskItems.map(i => i.json.risk_score || 0).sort((a, b) => a - b);
const n      = scores.length;

const HIGH_T = n > 0
  ? Math.max(scores[Math.floor(n * 0.75)] ?? 0, 0.40)
  : 0.40;

const LOW_T = n > 0
  ? Math.min(
      Math.max(scores[Math.floor(n * 0.25)] ?? 0, 0.15),
      HIGH_T - 0.01
    )
  : 0.15;

const labeled = riskItems.map((item, idx) => {
  const s     = item.json.risk_score || 0;
  const label = s >= HIGH_T ? 'High' : s >= LOW_T ? 'Medium' : 'Low';

  return {
    json: {
      ...item.json,
      risk_label:      label,
      risk_rank:       idx + 1,
      // ✅ Fixed percentile — highest risk = 100, lowest = 0
      risk_percentile: Math.round((1 - (idx / Math.max(n - 1, 1))) * 100),
      zone:            item.json.is_external ? 'Exterior' : 'Interior',
      // ✅ Removed location_tag — same as zone, redundant
    }
  };
});

const highCount   = labeled.filter(i => i.json.risk_label === 'High').length;
const mediumCount = labeled.filter(i => i.json.risk_label === 'Medium').length;
const lowCount    = labeled.filter(i => i.json.risk_label === 'Low').length;

const output = [
  {
    json: {
      _type:            'risk_register_summary',
      total_elements:   n,
      high_count:       highCount,
      medium_count:     mediumCount,
      low_count:        lowCount,
      high_threshold:   Math.round(HIGH_T * 1000) / 1000,
      low_threshold:    Math.round(LOW_T  * 1000) / 1000,
      threshold_method: 'dynamic_percentile_p75_p25',  // ✅ audit trail
      score_min:        scores[0]                ?? 0,
      score_max:        scores[n - 1]            ?? 0,
      score_median:     scores[Math.floor(n / 2)] ?? 0,
    }
  },
  ...others,
  ...labeled,
];

return output;

// Diagnostic BQI+Risk — dead-end inspector after Node 4.5
const items = $input.all();

const byType = {};
for (const i of items) {
  const t = i.json._type || 'untyped';
  byType[t] = (byType[t] || 0) + 1;
}

const modelSummary = items.find(i => i.json._type === 'bqi_model_summary')?.json    || {};
const riskSummary  = items.find(i => i.json._type === 'risk_register_summary')?.json || {};
const srccSummary  = items.find(i => i.json._type === 'srcc_summary')?.json          || {};
const coverage     = items.find(i => i.json._type === 'coverage_analysis')?.json     || {};
const riskEls      = items.filter(i => i.json._type === 'risk_element');

// Averages of the four BQI dimensions across all scored elements
const avg = key => riskEls.length
  ? Math.round(riskEls.reduce((s, i) => s + (i.json[key] || 0), 0) / riskEls.length * 1000) / 1000
  : null;

const top5 = riskEls
  .filter(i => (i.json.risk_rank || 999) <= 5)
  .sort((a, b) => a.json.risk_rank - b.json.risk_rank)
  .map(i => ({
    rank:        i.json.risk_rank,
    GlobalId:    (i.json.GlobalId || '').slice(0, 10),
    Category:    i.json.Category,
    D1:          i.json.score_completeness,
    D2:          i.json.score_validity,
    D3:          i.json.score_qto_coverage,
    D4:          i.json.score_qto_agreement,
    BQI:         i.json.bqi_score,
    L:           i.json.likelihood_score,
    C:           i.json.consequence_score,
    R_raw:       i.json.risk_score_raw,
    R_adj:       i.json.risk_score,
    band:        i.json.uncertainty_band,
    label:       i.json.risk_label,
    penalties:   i.json.penalties,
  }));

return [{
  json: {
    _diagnostic:      'bqi_risk_summary',
    item_counts:      byType,
    model_bqi:        modelSummary.model_bqi,
    model_confidence: modelSummary.model_confidence,
    pipeline_scored:  modelSummary.pipeline_scored,
    weights_used:     modelSummary.weights_used,
    dim_averages:     { D1: avg('score_completeness'), D2: avg('score_validity'),
                        D3: avg('score_qto_coverage'), D4: avg('score_qto_agreement') },
    alpha_used:       riskEls[0]?.json.alpha_used ?? null,
    thresholds:       { high: riskSummary.high_threshold, low: riskSummary.low_threshold,
                        method: riskSummary.threshold_method },
    risk_counts:      { high: riskSummary.high_count, medium: riskSummary.medium_count,
                        low: riskSummary.low_count },
    avg_srcc:         srccSummary.average_srcc,
    coverage_pct:     coverage.coverage_percentage,
    coverage_verdict: coverage.verdict,
  },
}, ...top5.map(t => ({ json: { _diagnostic: 'top5_risk', ...t } }))];
